    rgba(255, 255, 255, 0.022) 0 3px,
    transparent 3px 7px
  );
}
.cell-awake {
  background: rgba(255, 255, 255, 0.055);
  color: rgba(233, 242, 236, 0.88);
}
.cell-overlap {
  background: linear-gradient(180deg, rgba(61, 220, 151, 0.34), rgba(61, 220, 151, 0.17));
