  font-weight: 750;
  box-shadow:
    inset 0 0 0 1px rgba(61, 220, 151, 0.5),
    0 0 14px -4px rgba(61, 220, 151, 0.35);
}
.cell-sm {
  height: 28px;
  font-size: 10px;
  border-radius: 5px;
}
.cell-in {
  animation: cell-in 0.35s cubic-bezier(0.2, 0.7, 0.3, 1) both;
